function getPathaiTranslation(key, lang) {
    return (pathaiTranslations[lang] && pathaiTranslations[lang][key]) ||
           (pathaiTranslations.en && pathaiTranslations.en[key]) || null;
}

function applyPathaiTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.pathai.") || key.startsWith("review.common."))) {
            const translation = getPathaiTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    
}

window.addEventListener("languageChanged", e => setTimeout(() => applyPathaiTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyPathaiTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyPathaiTranslations(window.i18n?.getCurrentLanguage() || "en");
}
